export interface TransactionsTravelRuleConfirmOwnershipParams {
  /** true to confirm ownership, false to deny it. */
  confirmed: boolean;
  /** Inbound TRP transfers: the payment address Didit returns to the originating VASP when you approve. Defaults to the matched address book entry's address, then beneficiary_data.wallet_address. On a declared self-hosted wallet transfer that names no counterparty wallet, the wallet whose ownership you verified; without it the request is rejected with 400. Ignored for other transfers. */
  wallet_address?: string;
}

/** Send as JSON, or as multipart/form-data with the attachments in `files`. */
export interface TransactionsTravelRuleCreateMessageParams {
  kind?: "MESSAGE" | "DOCUMENT_REQUEST" | (string & {});
  /** Required for a MESSAGE unless a file is attached. */
  body?: string;
  /** Required (at least one) for a DOCUMENT_REQUEST, and only allowed there. */
  requested_documents?: string[];
  /** A message of the same transfer. A reply that carries a document fulfils the document request it answers. */
  reply_to?: string | null;
  /** Multipart only. Up to 5 files of 10 MB each. */
  files?: Uploadable[];
}

export interface TransactionsTravelRuleTriggerTestVaspInboundParams {
  /** The destination wallet address. The Didit Test VASP sends to it, matched against your wallet address book on the chain of the asset. A wallet with no matching entry is accepted and the inbound transaction is booked ON_HOLD. */
  beneficiary_wallet_address: string;
  /** What the Didit Test VASP declares the beneficiary to be. `accept` declares the holder's own name; `name_mismatch` declares a name no holder agrees with. The decision itself is always yours. */
  scenario?: "accept" | "name_mismatch" | (string & {});
  /** Chain of the asset. */
  chain?: string;
  /** Amount as a decimal string. */
  amount?: string;
  /** Asset code. */
  currency?: string;
  /** Optional idempotency key. A repeat with the same value returns the transfer the first call booked. */
  reference?: string;
}

/** Provide exactly one of: payment_txn_id (finish), action=cancel, action=resend, action=update_compliance_email with compliance_email, or action=update_originator_wallet with wallet_address. */
export interface TransactionsTravelRuleUpdateTransferParams {
  /** The on-chain transaction hash. Requires the transfer to be an outbound transfer in COMPLETED status. */
  payment_txn_id?: string;
  /** "cancel" cancels a non-terminal transfer. "resend" re-runs routing for an outbound transfer stuck in COUNTERPARTY_VASP_NOT_FOUND, COUNTERPARTY_VASP_NOT_REACHABLE, or NOT_ENOUGH_COUNTERPARTY_DATA. "update_compliance_email" replaces the compliance email the request goes to, on an outbound transfer in one of those three statuses; send "resend" afterwards. "update_originator_wallet" records the wallet the funds actually left from (`wallet_address`, `memo`). */
  action?:
    "cancel" | "resend" | "update_compliance_email" | "update_originator_wallet" | (string & {});
  /** Required with `action: update_compliance_email`. Kept as this transfer's `beneficiary_data.counterparty_vasp_email`: it belongs to this transfer only and joins no directory entry and no contact list. */
  compliance_email?: string;
  /** With `action: update_originator_wallet`: the wallet the funds left from. When the transfer's UTXO inputs are known it must be one of them. */
  wallet_address?: string;
  /** With `action: update_originator_wallet`: the wallet's memo or tag on a memo network. Optional. */
  memo?: string;
}
